export class PageCreatedHook implements Hook {
  event = "wiki.page_created";

  async handler(payload: { page: WikiPage }) {
    console.log(`[WikiHook] Page created: ${payload.page.title}`);

    // 可以在这里执行额外的处理逻辑
    // 例如：发送通知、更新索引、记录日志等
    await this.notifySubscribers(payload.page);
    await this.updateSearchIndex(payload.page);
  }

  private async notifySubscribers(page: WikiPage) {
    // 实现订阅者通知逻辑
    console.log(`[WikiHook] Notifying subscribers about new page: ${page.title}`);
  }

  private async updateSearchIndex(page: WikiPage) {
    // 实现搜索索引更新逻辑
    console.log(`[WikiHook] Updating search index for page: ${page.title}`);
  }
}

// 页面更新Hook
export class PageUpdatedHook implements Hook {
  event = "wiki.page_updated";

  async handler(payload: { page: WikiPage; previous_version: WikiPage }) {
    console.log(`[WikiHook] Page updated: ${payload.page.title}`);

    // 执行页面更新后的处理逻辑
    await this.recordChange(payload.page, payload.previous_version);
    await this.triggerReviewIfNeeded(payload.page);
  }

  private async recordChange(current: WikiPage, previous: WikiPage) {
    // 记录变更历史
    console.log(`[WikiHook] Recording change for page: ${current.title}`);
  }

  private async triggerReviewIfNeeded(page: WikiPage) {
    // 如果需要，触发审核流程
    if (page.status === 'draft') {
      console.log(`[WikiHook] Triggering review for page: ${page.title}`);
    }
  }
}
